#include <string>
#include <unordered_set>

class Solution {
public:
    int countVowelSubstrings(std::string word) {
        auto isVowel = [](char c) {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };

        int ans = 0;
        int n = word.size();

        for (int i = 0; i < n; ++i) {
            std::unordered_set<char> seen;
            for (int j = i; j < n; ++j) {
                if (!isVowel(word[j])) break;
                seen.insert(word[j]);
                if (seen.size() == 5) ans++;
            }
        }
        return ans;
    }
};

import java.util.HashSet;
import java.util.Set;

class Solution {
    public int countVowelSubstrings(String word) {
        int ans = 0;
        int n = word.length();

        for (int i = 0; i < n; i++) {
            Set<Character> seen = new HashSet<>();
            for (int j = i; j < n; j++) {
                char ch = word.charAt(j);
                if (!isVowel(ch)) break;
                seen.add(ch);
                if (seen.size() == 5) ans++;
            }
        }
        return ans;
    }

    private boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
}

